import itertools

def Q(x, y, z, a, b, c):
    """Calculates the value Ivan reports."""
    term1 = abs(x + y - a - b)
    term2 = abs(y + z - b - c)
    term3 = abs(z + x - c - a)
    return term1 + term2 + term3

# Test space for (x, y, z)
X_values = [0, 1, 2]
all_xyz = list(itertools.product(X_values, repeat=3))

# Query points (a, b, c)
queries = {
    "C1 (0, 0, 0)": (0, 0, 0),
    "C2 (9, 9, 9)": (9, 9, 9),
    "C3 (5, 5, 5)": (5, 5, 5)
}

results = {}

for name, (a, b, c) in queries.items():
    outputs = {}
    for x, y, z in all_xyz:
        output = Q(x, y, z, a, b, c)

        # Store mapping: output -> list of (x, y, z) that yield this output
        if output not in outputs:
            outputs[output] = []
        outputs[output].append((x, y, z))

    results[name] = outputs

# Analyze collisions
collision_findings = {}
for name, outputs in results.items():
    collisions = {k: v for k, v in outputs.items() if len(v) > 1}
    collision_findings[name] = collisions

print("--- RESULTS SUMMARY ---")
for name, outputs in results.items():
    print(f"\n--- Query: {name} ---")
    # Print mapping of unique outputs to the triplets that generated them
    for output, triplets in outputs.items():
        if len(triplets) == 1:
            print(f"Q={output}: {(triplets[0][0], triplets[0][1], triplets[0][2])}")
        else:
            print(f"Q={output}: {triplets} (COLLISION!)")

print("\n--- COLLISION ANALYSIS ---")
for name, collisions in collision_findings.items():
    print(f"\n{name} Collisions found:")
    if collisions:
        for output, triplets in collisions.items():
            print(f"  Q={output} is achieved by {len(triplets)} triplets: {triplets}")
    else:
        print("  No collisions found.")

